<?php
$root=require dirname(__DIR__).'/app/bootstrap.php';
use Digiti\Core\{DomainTools,RedisStore,Store,Uuid};
use Digiti\Domain\EdgeProviderFactory;
$loop=in_array('--loop',$argv,true);$worker=gethostname().':'.getmypid();
function processOne(string $worker): bool {
    $job=Store::one('SELECT job_guid,job_type,payload FROM jobs WHERE status="QUEUED" AND available_at<=NOW() ORDER BY available_at,created_at LIMIT 1');
    if($job){$claimed=Store::exec('UPDATE jobs SET status="RUNNING",locked_at=NOW(6),locked_by=?,attempts=attempts+1 WHERE job_guid=? AND status="QUEUED"',[$worker,Uuid::toBinary($job['job_guid'])]);if(!$claimed)return true;try{$payload=json_decode($job['payload']?:'{}',true)?:[];switch($job['job_type']){case'domain.revalidate':$domains=Store::all('SELECT domain_guid,hostname,verification_token,status,edge_metadata FROM domains WHERE status IN ("AWAITING_DNS","ROUTING_VALID","SSL_PROVISIONING","ACTIVE","REVALIDATION_FAILED") ORDER BY last_checked_at IS NULL DESC,last_checked_at ASC LIMIT 100');foreach($domains as$d){$dns=DomainTools::verifyDns($d['hostname'],$d['verification_token']);$status=$dns['verified']?($d['status']==='REVALIDATION_FAILED'?'ROUTING_VALID':$d['status']):'REVALIDATION_FAILED';$edge=json_decode($d['edge_metadata']?:'{}',true)?:[];if($dns['verified']&&in_array($d['status'],['ROUTING_VALID','SSL_PROVISIONING','ACTIVE'],true)){try{$edge=EdgeProviderFactory::make()->status($d['hostname'],$edge);if(($edge['status']??'')==='ACTIVE' && $d['status']!=='ACTIVE')$status='SSL_PROVISIONING';elseif($d['status']!=='ACTIVE')$status=$edge['status']??'SSL_PROVISIONING';}catch(Throwable$e){$edge['status_error']=$e->getMessage();}}Store::exec('UPDATE domains SET status=?,dns_metadata=?,edge_metadata=?,last_checked_at=NOW(6),updated_at=NOW(6) WHERE domain_guid=? AND status=?',[$status,json_encode($dns),json_encode($edge),Uuid::toBinary($d['domain_guid']),$d['status']]);RedisStore::del('domain:'.$d['hostname']);}break;case'payment.reconcile':$payments=Store::all('SELECT payment_guid FROM payments WHERE status IN ("PROCESSING","PENDING") AND updated_at<DATE_SUB(NOW(),INTERVAL 5 MINUTE) LIMIT 100');foreach($payments as$pay)Store::exec('UPDATE payments SET updated_at=NOW(6) WHERE payment_guid=?',[Uuid::toBinary($pay['payment_guid'])]);break;case'notification.dispatch':break;default:break;}Store::exec('UPDATE jobs SET status="COMPLETED",completed_at=NOW(6),locked_at=NULL,locked_by=NULL WHERE job_guid=?',[Uuid::toBinary($job['job_guid'])]);}catch(Throwable$e){Store::exec('UPDATE jobs SET status=IF(attempts>=5,"FAILED","QUEUED"),available_at=DATE_ADD(NOW(),INTERVAL 5 MINUTE),last_error=?,locked_at=NULL,locked_by=NULL WHERE job_guid=?',[substr($e->getMessage(),0,1000),Uuid::toBinary($job['job_guid'])]);}return true;}
    $event=Store::one('SELECT outbox_event_guid,event_type,payload FROM outbox_events WHERE status="PENDING" AND available_at<=NOW() ORDER BY available_at,created_at LIMIT 1');
    if($event){$claimed=Store::exec('UPDATE outbox_events SET status="PROCESSING",attempts=attempts+1 WHERE outbox_event_guid=? AND status="PENDING"',[Uuid::toBinary($event['outbox_event_guid'])]);if(!$claimed)return true;try{Store::exec('UPDATE outbox_events SET status="PROCESSED",processed_at=NOW(6) WHERE outbox_event_guid=?',[Uuid::toBinary($event['outbox_event_guid'])]);}catch(Throwable$e){Store::exec('UPDATE outbox_events SET status=IF(attempts>=5,"FAILED","PENDING"),available_at=DATE_ADD(NOW(),INTERVAL 5 MINUTE),last_error=? WHERE outbox_event_guid=?',[substr($e->getMessage(),0,1000),Uuid::toBinary($event['outbox_event_guid'])]);}return true;}return false;
}
do{$worked=processOne($worker);file_put_contents($root.'/storage/worker-heartbeat.json',json_encode(['worker'=>$worker,'at'=>gmdate('c')]),LOCK_EX);if($loop&&!$worked)sleep(2);}while($loop);
